import{_ as a,H as s,f as t,i as o}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"subagents","description":"","frontmatter":{},"headers":[],"relativePath":"ja/skills/subagents.md","filePath":"ja/skills/subagents.md"}'),d={name:"ja/skills/subagents.md"};function l(n,e,c,i,r,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="subagents" tabindex="-1">subagents <a class="header-anchor" href="#subagents" aria-label="Permalink to &quot;subagents&quot;">​</a></h1><p><code>subagents</code> スキルは、計画内の <code>[parallel]</code> タスクを独立コンテキストを持つサブエージェントへ派遣し、明確な役割契約（ROLE）と能力階層別モデル選択（MODEL）で並列実行と二段階レビューを行います。</p><h2 id="派遣と書き込み隔離" tabindex="-1">派遣と書き込み隔離 <a class="header-anchor" href="#派遣と書き込み隔離" aria-label="Permalink to &quot;派遣と書き込み隔離&quot;">​</a></h2><p>タスクの原子的展開は派遣時のみに行い、仕様や計画本文を貼り付けずファイルパスのみを渡します：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK: &lt;1行タスク&gt;</span></span>
<span class="line"><span>ROLE: &lt;implementer | spec-reviewer | quality-reviewer&gt;</span></span>
<span class="line"><span>MODEL: &lt;fast | balanced | strongest&gt;</span></span>
<span class="line"><span>REPOSITORY / MODULE / FILES / SPEC / ACCEPTANCE / EXTRA</span></span></code></pre></div><p>1タスクにつき1リポジトリ／1モジュールの書き込み範囲のみ許可され、重複するモジュールルートへ同時に書き込みエージェントを派遣しません。必要モジュールのローカル受入がすべて通過してから統合タスクを派遣し、<code>- [x]</code> の更新は Coordinator のみが行います。</p><h2 id="ロール循環とステータス対応" tabindex="-1">ロール循環とステータス対応 <a class="header-anchor" href="#ロール循環とステータス対応" aria-label="Permalink to &quot;ロール循環とステータス対応&quot;">​</a></h2><p>タスクごとの実行サイクル：<code>implementer</code>（デフォルト <code>balanced</code>） → <code>spec-reviewer</code>（デフォルト <code>fast</code>） → <code>quality-reviewer</code>（デフォルト <code>strongest</code>） → Coordinator が完了記録。返却ステータスを明示的に処理します：</p><ul><li><code>DONE_WITH_CONCERNS</code>: 正確性に関する懸念は修正し、参考所見は記録。</li><li><code>NEEDS_CONTEXT</code>: 不足事実を補って再派遣。</li><li><code>BLOCKED</code>: 根本要因を診断（文脈不足 / モデル能力不足 / 粒度過大 / 計画誤り）。無策で再試行しない。</li></ul><h2 id="モデル階層" tabindex="-1">モデル階層 <a class="header-anchor" href="#モデル階層" aria-label="Permalink to &quot;モデル階層&quot;">​</a></h2><p><code>MODEL</code>（<code>fast | balanced | strongest</code>）は未指定時にハーネスのデフォルトを使用します。<code>.praxis/model-tiers.yaml</code> で変更可能（解決順序: プロジェクト <code>.praxis/model-tiers.yaml</code> → ユーザー <code>~/.praxis/model-tiers.yaml</code> → ハーネスデフォルト。テンプレートは <code>model-tiers.example.yaml</code> の <code>tiers.&lt;tier&gt;.{provider, model}</code>）。</p>`,11)])])}const m=a(d,[["render",l]]);export{h as __pageData,m as default};
